    10→/**
    11→ * Lexer - Tokenizes FreeLang source code
    12→ */
    13→export class Lexer {
    14→  private input: string;
    15→  private position: number = 0;
    16→  private line: number = 1;
    17→  private column: number = 0;
    18→  private current: string = '';
    19→  private lastTokenType: TokenType = TokenType.EOF;  // Track last token for regex disambiguation
    20→
    21→  constructor(input: string) {
    22→    this.input = input;
    23→    this.readChar();
    24→  }
    25→
    26→  /**
    27→   * Read next character
    28→   */
    29→  private readChar(): void {
    30→    if (this.position >= this.input.length) {
    31→      this.current = '\0';
    32→    } else {
    33→      this.current = this.input[this.position];
    34→    }
    35→    this.position++;
    36→    this.column++;
    37→  }
    38→
    39→  /**
    40→   * Peek at next character without consuming
    41→   */
    42→  private peekChar(): string {
    43→    if (this.position >= this.input.length) {
    44→      return '\0';
    45→    }
    46→    return this.input[this.position];
    47→  }
    48→
    49→  /**
    50→   * Skip whitespace
    51→   */
    52→  private skipWhitespace(): void {
    53→    while (this.current === ' ' || this.current === '\t' || this.current === '\r') {
    54→      this.readChar();
    55→    }
    56→  }
    57→
    58→  /**
    59→   * Skip single-line comment
    60→   */
    61→  private skipComment(): void {
    62→    // Skip //
    63→    this.readChar();
    64→    this.readChar();
    65→
    66→    // Read until newline
    67→    while (this.current !== '\n' && this.current !== '\0') {
    68→      this.readChar();
    69→    }
    70→  }
    71→
    72→  /**
    73→   * Skip multi-line comment
    74→   */
    75→  private skipMultiLineComment(): void {
    76→    // Skip /*
    77→    this.readChar();
    78→    this.readChar();
    79→
    80→    while (true) {
    81→      if (this.current === '\0') {
    82→        break;
    83→      }
    84→
    85→      if (this.current === '\n') {
    86→        this.line++;
    87→        this.column = 0;
    88→      }
    89→
    90→      if (this.current === '*' && this.peekChar() === '/') {
    91→        this.readChar(); // *
    92→        this.readChar(); // /
    93→        break;
    94→      }
    95→
    96→      this.readChar();
    97→    }
    98→  }
    99→
