   101→   * Read identifier or keyword
   102→   */
   103→  private readIdentifier(): string {
   104→    const start = this.position - 1;
   105→    while (this.isIdentifierChar(this.current)) {
   106→      this.readChar();
   107→    }
   108→    return this.input.substring(start, this.position - 1);
   109→  }
