     1→// FreeLang v2 - IR to C code generator
     2→// Converts AI's IR to compilable C code.
     3→
     4→import { Op, Inst, AIIntent, CompileResult } from './types';
     5→import { getBuiltinC } from './engine/builtins';
     6→import { LibraryResolver } from './codegen/library-resolver';
     7→
     8→export class CodeGen {
     9→  private resolver: LibraryResolver;
    10→
    11→  constructor() {
    12→    this.resolver = new LibraryResolver();
    13→  }
    14→
    15→  generate(intent: AIIntent): string {
    16→    const lines: string[] = [];
    17→
    18→    // Use LibraryResolver to determine headers based on directive
    19→    const profile = this.resolver.resolveFromHeader({
    20→      fn: intent.fn,
    21→      input: intent.params.length > 0 ? intent.params[0].type : 'void',
    22→      output: intent.ret,
    23→      reason: 'Generated code',
    24→      directive: 'memory', // default directive (speed | memory | safety)
    25→      complexity: 'O(n)',
    26→      confidence: 0.95, // 0.0-1.0 범위
    27→      matched_op: intent.fn,
    28→    });
    29→
    30→    const includes = profile.headers;
    31→    const linkerFlags = profile.linkerFlags;
    32→
    33→    // Includes
    34→    for (const h of includes) {
    35→      lines.push(`#include <${h}>`);
    36→    }
    37→    lines.push('');
    38→
    39→    // Function signature
    40→    const retC = this.typeToC(intent.ret);
    41→    const paramsC = intent.params
    42→      .map(p => {
    43→        const isArray = p.type.startsWith('array<');
    44→        return `${this.typeToC(p.type)} ${p.name}${isArray ? `, int ${p.name}_len` : ''}`;
    45→      })
    46→      .join(', ');
    47→    lines.push(`${retC} ${intent.fn}(${paramsC || 'void'}) {`);
    48→
    49→    // Local vars
    50→    const locals = new Set<string>();
    51→    const arrays = new Set<string>();
    52→
    53→    for (const inst of intent.body) {
    54→      if (inst.op === Op.STORE && typeof inst.arg === 'string') locals.add(inst.arg);
    55→      if (inst.op === Op.ARR_NEW && typeof inst.arg === 'string') arrays.add(inst.arg);
    56→    }
    57→
    58→    // Stack simulation for C
    59→    lines.push('    double _stack[1024];');
    60→    lines.push('    int _sp = 0;');
    61→    if (locals.size > 0) {
    62→      for (const v of locals) {
    63→        lines.push(`    double ${this.safeName(v)} = 0;`);
    64→      }
    65→    }
    66→    lines.push('');
    67→
    68→    // Emit instructions
    69→    for (let i = 0; i < intent.body.length; i++) {
    70→      const inst = intent.body[i];
    71→      const c = this.emitInst(inst, intent, i);
    72→      if (c) lines.push('    ' + c);
    73→    }
    74→
    75→    lines.push('}');
    76→    lines.push('');
    77→
    78→    // main() for testing
    79→    lines.push('int main(void) {');
    80→    lines.push(this.emitTestMain(intent));
    81→    lines.push('    return 0;');
    82→    lines.push('}');
    83→
    84→    return lines.join('\n') + '\n';
    85→  }
    86→
    87→  private emitInst(inst: Inst, intent: AIIntent, idx: number): string {
    88→    switch (inst.op) {
    89→      case Op.PUSH:
    90→        return `_stack[_sp++] = ${inst.arg};`;
    91→
    92→      case Op.POP:
    93→        return '_sp--;';
    94→
    95→      case Op.DUP:
    96→        return '_stack[_sp] = _stack[_sp-1]; _sp++;';
    97→
    98→      case Op.ADD: return this.emitBinop('+');
    99→      case Op.SUB: return this.emitBinop('-');
   100→      case Op.MUL: return this.emitBinop('*');
   101→      case Op.DIV:
   102→        return '{ double _b = _stack[--_sp]; double _a = _stack[--_sp]; _stack[_sp++] = _b != 0 ? _a / _b : 0; }';
   103→      case Op.MOD:
   104→        return '{ double _b = _stack[--_sp]; double _a = _stack[--_sp]; _stack[_sp++] = (int)_a % (int)_b; }';
   105→      case Op.NEG:
   106→        return '_stack[_sp-1] = -_stack[_sp-1];';
   107→
   108→      case Op.EQ:  return this.emitCmp('==');
   109→      case Op.NEQ: return this.emitCmp('!=');
   110→      case Op.LT:  return this.emitCmp('<');
   111→      case Op.GT:  return this.emitCmp('>');
   112→      case Op.LTE: return this.emitCmp('<=');
   113→      case Op.GTE: return this.emitCmp('>=');
   114→
   115→      case Op.AND: return this.emitBinop('&&');
   116→      case Op.OR:  return this.emitBinop('||');
   117→      case Op.NOT:
   118→        return '_stack[_sp-1] = !_stack[_sp-1];';
   119→
   120→      case Op.STORE:
   121→        return `${this.safeName(inst.arg as string)} = _stack[--_sp];`;
   122→
   123→      case Op.LOAD:
   124→        return `_stack[_sp++] = ${this.safeName(inst.arg as string)};`;
   125→
   126→      case Op.JMP:
   127→        return `goto _L${inst.arg};`;
   128→
   129→      case Op.JMP_IF:
   130→        return `if (_stack[--_sp]) goto _L${inst.arg};`;
   131→
   132→      case Op.JMP_NOT:
   133→        return `if (!_stack[--_sp]) goto _L${inst.arg};`;
   134→
   135→      case Op.RET:
   136→        return 'return _stack[--_sp];';
   137→
   138→      case Op.HALT:
   139→        return 'return _stack[_sp > 0 ? _sp-1 : 0];';
